# Generated by prochitecture_gn/experiments/streets/blosm_integration/package_runtime.py
# Source: experiments/streets/stage5/editable_input/unified_curve_nodes.py
# Source SHA256: a62d688b401c47730b8f1ba324ffc89951af0812ec8d73499a156121321a4dee
"""Build a validated, trimmed native curve for one actual Section path.

Topology records identify source samples; edited positions and dimensions are
read directly by Geometry Nodes. The first surface pass retains one curve per
record so paired divided carriageways can share row counts without sharing
centerline coordinates or requiring identical control-point counts.
"""


def construct(g, sources, paths, mouths, iteration, inp, index, pos):
    def meta(name, kind='INT'):
        return g.sample(paths, g.named(name, kind), iteration, kind)

    start = meta('st_path_start')
    npoints = meta('st_path_count')
    last = g.math('SUBTRACT', npoints, 1)
    end = g.math('ADD', start, last)
    first_edge = meta('st_path_edge')
    section_id = meta('st_path_id')
    divided = meta('st_path_divided', 'BOOLEAN')
    inner_u = meta('st_path_inner_u', 'FLOAT')
    partner = meta('st_path_partner')
    partner_reversed = meta('st_path_partner_reversed', 'BOOLEAN')
    make_grass = meta('st_path_make_grass', 'BOOLEAN')
    bundle_id = meta('st_path_bundle_id')
    attached = [meta('st_path_attached_'+suffix, 'BOOLEAN') for suffix in ('start', 'end')]
    rise, datum = [meta('st_path_'+name, 'FLOAT') for name in ('rise', 'datum')]
    width = g.sample(sources, g.named('st_width', 'FLOAT'), first_edge, 'FLOAT', 'EDGE')
    offset = g.sample(sources, g.named('st_offset', 'FLOAT'), first_edge, 'FLOAT', 'EDGE')
    checks = [g.compare(npoints, 2, 'GREATER_EQUAL', 'INT'),
              g.compare(width, 0., 'GREATER_THAN'),
              g.compare(rise, 0., 'GREATER_EQUAL'),
              g.compare(inp.outputs['Cell Size'], 0., 'GREATER_THAN'),
              g.compare(inp.outputs['Radial Samples'], 1, 'GREATER_EQUAL', 'INT'),
              g.compare(inp.outputs['Mesh Resolution'], 1, 'GREATER_EQUAL', 'INT'),
              g.compare(inp.outputs['Mesh Resolution'], 4, 'LESS_EQUAL', 'INT'),
              g.switch(divided, True, g.all(
                  g.either(g.close(inner_u, 0.), g.close(inner_u, 1.)),
                  g.close(g.math('MODULO', inp.outputs['Radial Samples'], 4.), 0.)), 'BOOLEAN')]

    line = g.node('GeometryNodeMeshLine', 'Full ordered authored Section vertices')
    g.set(npoints, line.inputs['Count'])
    source_index = g.math('ADD', start, index)
    original_position = g.sample(sources, pos, source_index, 'FLOAT_VECTOR')
    source_is_first = g.compare(index, 0, 'EQUAL', 'INT')
    source_is_last = g.compare(index, last, 'EQUAL', 'INT')
    authored_positions = g.node('GeometryNodeSetPosition', 'Validate every actual authored sample')
    g.set(line.outputs['Mesh'], authored_positions.inputs['Geometry'])
    g.set(original_position, authored_positions.inputs['Position'])
    authored = authored_positions.outputs['Geometry']

    # Validate the authored source identities/connectivity, independently of this
    # ordered helper line, before it can conceal any unsupported topology edit.
    expected_role = g.switch(source_is_first, g.switch(source_is_last, 0, 2, 'INT'), 1, 'INT')
    points_ok = g.all(
        g.compare(g.sample(sources, g.named('st_live_vertex_index'), source_index), source_index, 'EQUAL', 'INT'),
        g.compare(g.sample(sources, g.named('st_endpoint_role'), source_index), expected_role, 'EQUAL', 'INT'),
        g.close(g.component(original_position, 'Z'), datum))
    checks.append(g.stat(authored, points_ok))
    edge_index = g.math('ADD', first_edge, index)
    edge_v = g.node('GeometryNodeInputMeshEdgeVertices', 'Actual editable edge connectivity')
    actual0 = g.sample(sources, edge_v.outputs['Vertex Index 1'], edge_index, 'INT', 'EDGE')
    actual1 = g.sample(sources, edge_v.outputs['Vertex Index 2'], edge_index, 'INT', 'EDGE')
    expected1 = g.math('ADD', source_index, 1)
    connectivity = g.either(
        g.all(g.compare(actual0, source_index, 'EQUAL', 'INT'), g.compare(actual1, expected1, 'EQUAL', 'INT')),
        g.all(g.compare(actual1, source_index, 'EQUAL', 'INT'), g.compare(actual0, expected1, 'EQUAL', 'INT')))
    edges_ok = g.all(connectivity,
        g.compare(g.sample(sources, g.named('st_live_edge_index'), edge_index, 'INT', 'EDGE'), edge_index, 'EQUAL', 'INT'),
        g.compare(g.sample(sources, g.named('st_section_id'), edge_index, 'INT', 'EDGE'), section_id, 'EQUAL', 'INT'),
        g.close(g.sample(sources, g.named('st_width', 'FLOAT'), edge_index, 'FLOAT', 'EDGE'), width),
        g.close(g.sample(sources, g.named('st_offset', 'FLOAT'), edge_index, 'FLOAT', 'EDGE'), offset),
        g.compare(g.vector('DISTANCE', edge_v.outputs['Position 1'], edge_v.outputs['Position 2']), .001, 'GREATER_THAN'))
    checks.append(g.stat(authored, edges_ok, 'EDGE'))

    # Collinear editing samples must not shorten a geometric bend's allowance.
    # Filter only the temporary curve; every authored sample stays independently
    # validated and becomes an active bend immediately when moved off its line.
    before = g.sample(authored, pos, g.math('MAXIMUM', g.math('SUBTRACT', index, 1), 0), 'FLOAT_VECTOR')
    after = g.sample(authored, pos, g.math('MINIMUM', g.math('ADD', index, 1), last), 'FLOAT_VECTOR')
    incoming = g.vector('NORMALIZE', g.vector('SUBTRACT', pos, before))
    outgoing = g.vector('NORMALIZE', g.vector('SUBTRACT', after, pos))
    collinear = g.all(
        g.compare(g.vector('LENGTH', g.vector('CROSS_PRODUCT', incoming, outgoing)), 1e-6, 'LESS_EQUAL'),
        g.compare(g.vector('DOT_PRODUCT', incoming, outgoing), 0., 'GREATER_THAN'))
    keep = g.either(g.either(source_is_first, source_is_last), g.boolean('NOT', collinear))
    points = g.node('GeometryNodeMeshToPoints', 'Keep geometric turns without deleting editable vertices')
    points.mode = 'VERTICES'
    g.set(authored, points.inputs['Mesh'])
    g.set(keep, points.inputs['Selection'])
    to_curve = g.node('GeometryNodePointsToCurves', 'Ordered geometric path independent of subdivision')
    g.set(points.outputs['Points'], to_curve.inputs['Points'])
    g.set(index, to_curve.inputs['Weight'])
    simplified = to_curve.outputs['Curves']
    simplified_count = g.node('GeometryNodeAttributeDomainSize', 'Effective geometric turn count')
    simplified_count.component = 'CURVE'
    g.set(simplified, simplified_count.inputs['Geometry'])
    last = g.math('SUBTRACT', simplified_count.outputs['Point Count'], 1.)

    endpoint_positions = []
    endpoint_tangents = []
    for at, neighbor, connected, is_end in [
        (start, 1, attached[0], False),
        (end, g.math('SUBTRACT', last, 1), attached[1], True),
    ]:
        original = g.sample(sources, pos, at, 'FLOAT_VECTOR')
        original_neighbor = g.sample(simplified, pos, neighbor, 'FLOAT_VECTOR')
        outward = g.vector('NORMALIZE', g.vector('SUBTRACT', original_neighbor, original))
        nearest = g.node('GeometryNodeSampleNearest', 'Endpoint ID lookup in generated mouths')
        nearest.domain = 'POINT'
        g.set(mouths, nearest.inputs['Geometry'])
        g.set(g.xyz(at), nearest.inputs['Sample Position'])
        mouth_at = nearest.outputs['Index']

        def mouth(name, kind='FLOAT'):
            return g.sample(mouths, g.named('st_mouth_'+name, kind), mouth_at, kind)

        mouth_tangent = mouth('tangent', 'FLOAT_VECTOR')
        directed = g.vector('SCALE', mouth_tangent, -1. if is_end else 1.)
        free_directed = g.vector('SCALE', outward, -1. if is_end else 1.)
        tangent = g.switch(connected, free_directed, directed, 'VECTOR', 'Exact seam tangent')
        centerline_mouth = g.vector('SUBTRACT', mouth('position', 'FLOAT_VECTOR'), g.vector('SCALE', g.right(directed), offset))
        p = g.switch(connected, original, centerline_mouth, 'VECTOR', 'Trim attached endpoint before filleting')
        endpoint_positions.append(p)
        endpoint_tangents.append(tangent)
        trim = mouth('trim')
        remaining = g.math('SUBTRACT', g.vector('DISTANCE', original_neighbor, original), trim)
        expected_mouth = g.vector('ADD', original, g.vector('SCALE', outward, trim))
        matching = g.all(
            g.compare(mouth('key', 'INT'), at, 'EQUAL', 'INT'),
            g.close(mouth('width'), width), g.close(mouth('rise'), rise),
            g.compare(mouth('divided', 'BOOLEAN'), divided, 'EQUAL', 'INT'),
            g.switch(divided, True, g.close(mouth('inner_u'), inner_u), 'BOOLEAN'),
            g.close(mouth('datum'), datum),
            g.compare(mouth('nv', 'INT'), inp.outputs['Radial Samples'], 'EQUAL', 'INT'),
            g.compare(trim, 0., 'GREATER_EQUAL'),
            g.compare(remaining, .001, 'GREATER_THAN'),
            g.compare(g.vector('DISTANCE', centerline_mouth, expected_mouth), 2e-4, 'LESS_EQUAL'),
            g.compare(g.vector('DISTANCE', mouth_tangent, outward), 1e-4, 'LESS_EQUAL'))
        checks.append(g.switch(connected, True, matching, 'BOOLEAN', 'Attached endpoint contract'))

    is_first = g.compare(index, 0, 'EQUAL', 'INT')
    is_last = g.compare(index, last, 'EQUAL', 'INT')
    position = g.switch(is_first, pos, endpoint_positions[0], 'VECTOR')
    position = g.switch(is_last, position, endpoint_positions[1], 'VECTOR')
    setpos = g.node('GeometryNodeSetPosition', 'Live simplified path with exact trimmed mouth endpoints')
    g.set(simplified, setpos.inputs['Geometry'])
    g.set(position, setpos.inputs['Position'])
    polyline = setpos.outputs['Geometry']
    # For a two-vertex Section, individually valid trims may still overlap.
    # Both residual end legs must retain their original directed tangent.
    trimmed_first_next = g.sample(polyline, pos, 1, 'FLOAT_VECTOR')
    trimmed_last_previous = g.sample(polyline, pos, g.math('SUBTRACT', last, 1), 'FLOAT_VECTOR')
    for residual, tangent in [
        (g.vector('SUBTRACT', trimmed_first_next, endpoint_positions[0]), endpoint_tangents[0]),
        (g.vector('SUBTRACT', endpoint_positions[1], trimmed_last_previous), endpoint_tangents[1]),
    ]:
        checks.append(g.all(g.compare(g.vector('LENGTH', residual), .001, 'GREATER_THAN'),
                            g.compare(g.vector('DISTANCE', g.vector('NORMALIZE', residual), tangent), 1e-4, 'LESS_EQUAL')))

    previous = g.sample(polyline, pos, g.math('MAXIMUM', g.math('SUBTRACT', index, 1), 0), 'FLOAT_VECTOR')
    following = g.sample(polyline, pos, g.math('MINIMUM', g.math('ADD', index, 1), last), 'FLOAT_VECTOR')
    incoming = g.vector('SUBTRACT', pos, previous)
    outgoing = g.vector('SUBTRACT', following, pos)
    len_in, len_out = [g.vector('LENGTH', v) for v in (incoming, outgoing)]
    dot = g.vector('DOT_PRODUCT', g.vector('NORMALIZE', incoming), g.vector('NORMALIZE', outgoing))
    cosine = g.math('MAXIMUM', -1., g.math('MINIMUM', 1., dot))
    angle = g.math('ARCCOSINE', cosine)
    half_tan = g.math('TANGENT', g.math('MULTIPLY', angle, .5))
    cutback = g.math('MULTIPLY', .45, g.math('MINIMUM', len_in, len_out))
    available_radius = g.math('DIVIDE', cutback, g.math('MAXIMUM', half_tan, 1e-6))
    requested_radius = g.math('MULTIPLY', 1.5, width)
    radius = g.math('MINIMUM', requested_radius, available_radius)
    min_radius = g.math('ADD', width, g.math('MULTIPLY', 2., g.math('ABSOLUTE', offset)))
    interior = g.boolean('NOT', g.either(is_first, is_last))
    bent = g.compare(angle, 1e-4, 'GREATER_THAN')
    bend_ok = g.either(g.boolean('NOT', g.all(interior, bent)),
        g.all(g.compare(radius, min_radius, 'GREATER_EQUAL'), g.compare(angle, 2.61799387799, 'LESS_THAN')))
    checks.append(g.stat(polyline, bend_ok))
    radii = g.store(polyline, 'st_path_fillet_radius', g.switch(g.all(interior, bent), 0., radius))
    # The final Valid output also depends on the generated faces. Reject an
    # invalid turn *before* invoking Fillet Curve, so a crossed/overtrimmed path
    # cannot produce a NaN length which Mesh Grid would convert to an unsafe
    # allocation count while evaluating that final validity. This fallback is
    # computational only: checks remain false and no invalid surface is output.
    fallback = g.node('GeometryNodeCurvePrimitiveLine', 'Safe computation for rejected paths')
    fallback.inputs['Start'].default_value = (0., 0., 0.)
    fallback.inputs['End'].default_value = (1., 0., 0.)
    safe_radii = g.switch(g.all(*checks), fallback.outputs['Curve'], radii,
                         'GEOMETRY', 'Validate turns before native fillet evaluation')
    fillet = g.node('GeometryNodeFilletCurve', 'Smooth bounded circular-arc turns')
    fillet.inputs['Mode'].default_value = 'Bézier'
    fillet.inputs['Limit Radius'].default_value = True
    g.set(safe_radii, fillet.inputs['Curve'])
    g.set(g.named('st_path_fillet_radius', 'FLOAT'), fillet.inputs['Radius'])
    resolution = g.node('GeometryNodeSetSplineResolution', 'Accurate arc-length sampling')
    g.set(fillet.outputs['Curve'], resolution.inputs['Curve'])
    resolution.inputs['Resolution'].default_value = 96
    curve = resolution.outputs['Geometry'] if 'Geometry' in resolution.outputs else resolution.outputs[0]
    length = g.node('GeometryNodeCurveLength', 'Trimmed filleted Section length')
    g.set(curve, length.inputs['Curve'])
    curve_length = length.outputs['Length']
    finite_length = g.all(g.compare(curve_length, .001, 'GREATER_THAN'),
                          g.compare(curve_length, 1e20, 'LESS_THAN'))
    checks.append(finite_length)
    # The finite bound is far beyond usable scene distances and exists solely
    # to stop infinities reaching float-to-integer sampling conversions.
    curve = g.switch(finite_length, fallback.outputs['Curve'], curve,
                     'GEOMETRY', 'Finite curve length before grid sampling')
    curve_length = g.switch(finite_length, 1., curve_length)
    values = {
        'order': (iteration, 'INT'),
        'id': (section_id, 'INT'), 'width': (width, 'FLOAT'),
        'offset': (offset, 'FLOAT'), 'rise': (rise, 'FLOAT'),
        'datum': (datum, 'FLOAT'), 'length': (curve_length, 'FLOAT'),
        'divided': (divided, 'BOOLEAN'), 'inner_u': (inner_u, 'FLOAT'),
        'partner': (partner, 'INT'), 'reversed': (partner_reversed, 'BOOLEAN'),
        'make_grass': (make_grass, 'BOOLEAN'), 'bundle_id': (bundle_id, 'INT'),
        'start': (endpoint_positions[0], 'FLOAT_VECTOR'),
        'end': (endpoint_positions[1], 'FLOAT_VECTOR'),
        'start_tangent': (endpoint_tangents[0], 'FLOAT_VECTOR'),
        'end_tangent': (endpoint_tangents[1], 'FLOAT_VECTOR'),
    }
    for name, (value, kind) in values.items():
        curve = g.store(curve, 'st_sweep_'+name, value, kind, 'CURVE')
    return curve, g.all(*checks)
